# SPDX-License-Identifier: AGPL-3.0-only
"""Finalize only obtained first-batch software evidence, without rerunning studies."""
import hashlib,json,os,re,shutil,subprocess,tarfile
from pathlib import Path
ROOT=Path("/Users/juanyanez/Documents/Codex/2026-10-20/agent-braid-verified-core")
OUT=Path(__file__).resolve().parent
DEST=ROOT/"specs/029-system-one-evaluation/evidence/ddp-t02-t04"
REPORT=ROOT/"specs/028-system-one-core/decision-delivery/addenda/ddp-t02-t04-implementation.md"
PYTHON=Path("/Users/juanyanez/Repos/Personal/agent-braid-system-one/.venv-speckit/bin/python")
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2,sort_keys=True)+"\n")
def main():
    if DEST.exists() or REPORT.exists() or (OUT/"completion.json").exists():raise ValueError("existing finalization refused; retain attempts")
    profiles={n:json.loads((OUT/"profiles"/(n+".json")).read_text()) for n in ("quick","pr")}
    for n,r in profiles.items():
        if r.get("exitCode")!=0 or not r.get("sourceInputsStillMatch"):raise ValueError("profile not passed:"+n)
        if not all(sha(ROOT/p)==h for p,h in r["inputHashes"].items()):raise ValueError("profile source drift:"+n)
        if sha(OUT/"profiles"/(n+".log"))!=r["logSha256"]:raise ValueError("profile log drift")
    before=json.loads((OUT/"baseline-files.json").read_text())
    if not all(sha(ROOT/n)==h for n,h in before.items()):raise ValueError("legacy source changed")
    pin=json.loads((OUT/"serial-pin.json").read_text())
    if sha(ROOT/"agent_braid/system_one_verified_ir.py")!=pin["verifierSha256"]:raise ValueError("verifier drift")
    if sha(ROOT/"agent_braid/system_one_verified_registry.py")!=pin["registryAfterSha256"]:raise ValueError("registry drift")
    paths=sorted(set(subprocess.check_output(["git","ls-files","--others","--exclude-standard","-z"],cwd=ROOT).decode().rstrip("\0").split("\0")))
    paths=[n for n in paths if n and n!=".venv-speckit" and (ROOT/n).is_file()]
    codepins={n:sha(ROOT/n) for n in paths}
    summary={n:{"exitCode":r["exitCode"],"seconds":r["seconds"],"sourceInputsStillMatch":r["sourceInputsStillMatch"],"unitSuite":re.findall(r"Ran (\d+) tests in ([0-9.]+)s",(OUT/"profiles"/(n+".log")).read_text()),"skips":re.findall(r"OK \(skipped=(\d+)\)",(OUT/"profiles"/(n+".log")).read_text())} for n,r in profiles.items()}
    DEST.mkdir(parents=True)
    for f in sorted(OUT.iterdir()):
        if f.is_file():shutil.copy2(f,DEST/f.name)
    shutil.copytree(OUT/"profiles",DEST/"profiles")
    REPORT.parent.mkdir(parents=True,exist_ok=True)
    body=["<!-- SPDX-License-Identifier: CC-BY-SA-4.0 -->","# DDP-T02/T03/T04 — First implementation batch","","Local internal software delivery against public baseline fe6d25b3d9fb989c230aa11779b6a51d494d7a4e. No existing tracked source, public API, CLI/MCP discovery, historical assurance or research packet was changed. T01 contracts remain proposed public schemas; this delivery implements internal components only.","","## Implemented and checked","","- T02: pure finite EOF-aware IR, exact EN/ES symbolic/controlled grammar, complete offered-plan verification, minimum-cost/lexical selection and frozen records. Twenty-five focused tests and four targeted mutation controls passed.","- T03: observed effects from explicitly owned synthetic local repositories, exact immutable source/declared bindings, two to four operations, multiple files/hunks, read-only source checks and the injected shared Git budget/cancellation seam. Thirteen focused tests passed.","- T04: static single-domain registry, exact identities and bounded actual source-byte verification. Ten focused tests passed; coordinator subsequently pinned the final IR source and tested actual-pin success and changed-source refusal.","- Four coordinator integration tests join acquisition, IR, both languages/representations and actual registry identity, preserve shared counters/cancellation, and check fresh imports load no research or neural packages. The combined focused suite passed52 tests with zero skips in12.403 seconds.","","## Stable validation","",json.dumps(summary,indent=2),"","Quick escalated to sensitive validation under the existing path map. Both profiles used independent source-equivalent local full clones with existing isolated Python3.12 dependencies and explicit child PATH; no downloads, provider calls, paid CI or new infrastructure. These checks are software validation, not clean-room or scientific reproduction. Complete logs and exact input hashes are in the bound packet.","","## Semantics, limits and handoff","","The internal functions raise fixed ValueError codes on invalid/exhausted work; T05 must construct the complete external refused envelope. Source-validation hunks nested in interpret/render consume the shared verification counter. T03 fixes safe Git diff context3/Myers/interhunk0/color/prefix behavior and binds the actual acquired bytes; byte parity with historical acquisition under nondefault Git configuration is not claimed. Raw JSON duplicate rejection must happen at T05 ingress before a Mapping exists. Cancellation is cooperative within declared trusted owned-fixture assumptions; no universal hard deadline or same-UID hostile isolation is claimed. Optional Ruff was unavailable and was not installed.","","T02/T03/T04 component and join engineering checks are obtained. T05 is next: implement the complete typed wire result, admitted raw request and request-local context using these frozen interfaces. Then T06 binds unchanged native consumers with explicit stage budgets/freshness/cleanup evidence; T07 compatibility and independent review and T08 packaging/adoption gates follow. No T05/T06 implementation, native evaluation, production activation or public exposure is supplied by this batch.","","No experimental population was generated or evaluated. The previous experimental ledger remains unchanged; software checks are accounted separately. No model, training, calibration, human review, scientific/representative acceptance, data admission, promotion, activation, remote publication or Laya parity is claimed. EUR0 external spend and executionAuthorization=false throughout.","","The managed worktree preflight failed on shared-store unreachable objects; the documented independent-clone recovery passed with existing public pinned history. An initial history-helper attempt rejected a local origin URL; it was corrected to the verified public origin using already-local object pins. Prerequisites required explicit SPEC028 directory selection; no feature scaffold/assurance was regenerated. All attempts are retained.","","Read the frozen package plan and the documentary conversation's central corpus/RESUMPTION. That separate documentary branch records additive updates; this implementation branch does not silently merge or overwrite it. No remote task is closed here. The worker receipts retain pre-pin registry hashes; serial-pin.json explicitly records the changed registry hash and final IR pin.","",f"[Bound software packet]({os.path.relpath(DEST/'packet.json',REPORT.parent)})",""]
    REPORT.write_text("\n".join(body))
    with tarfile.open(DEST/"new-source.tar.gz","w:gz") as archive:
        for n in paths+[str(REPORT.relative_to(ROOT))]:archive.add(ROOT/n,arcname=n,recursive=False)
    save(DEST/"packet.json",{"status":"packaging","executionAuthorization":False})
    env={**os.environ,"PATH":str(PYTHON.parent)+os.pathsep+os.environ["PATH"],"PYTHONDONTWRITEBYTECODE":"1","GIT_ALLOW_PROTOCOL":"file"}
    with (DEST/"final-repository.log").open("x") as log:r=subprocess.run([str(PYTHON),"scripts/validate_repository.py"],cwd=ROOT,env=env,stdout=log,stderr=subprocess.STDOUT)
    if r.returncode:raise ValueError("final repository validation failed; log retained")
    names=set(codepins)|{str(REPORT.relative_to(ROOT))}|{str(p.relative_to(ROOT)) for p in DEST.rglob("*") if p.is_file() and p.name!="packet.json"}
    packet={"status":"complete","baseline":"fe6d25b3d9fb989c230aa11779b6a51d494d7a4e","bindings":{n:sha(ROOT/n) for n in sorted(names)},"baselineFilesPreserved":len(before),"focusedTests":52,"profiles":summary,"sourcePin":pin,"domain":"t024-eof-context-v1","delivery":"internal components and software join; no T05/T06 or active catalogue","independentReview":"pending","humanReview":"pending","training":"pending","activation":"pending","externalSpendEUR":0,"executionAuthorization":False}
    save(DEST/"packet.json",packet)
    if not all(sha(ROOT/n)==h for n,h in packet["bindings"].items()):raise ValueError("packet binding drift")
    subprocess.run(["git","add","--intent-to-add","--",*paths,str(REPORT.relative_to(ROOT)),str(DEST.relative_to(ROOT))],cwd=ROOT,check=True)
    with (OUT/"candidate.patch").open("w") as f:subprocess.run(["git","diff","--binary","fe6d25b3d9fb989c230aa11779b6a51d494d7a4e","--"],cwd=ROOT,stdout=f,check=True)
    result={"status":"complete","packet":str((DEST/"packet.json").relative_to(ROOT)),"packetSha256":sha(DEST/"packet.json"),"report":str(REPORT),"bindingsVerified":len(packet["bindings"]),"patchSha256":sha(OUT/"candidate.patch"),"executionAuthorization":False}
    save(OUT/"completion.json",result);print(json.dumps(result,indent=2),flush=True)
if __name__=="__main__":main()
